command:
let hero = game.user.character;

if (!hero) {
  const controlled = canvas.tokens.controlled;
  hero = controlled.find(t => t.actor?.effects.some(fx => fx.name.toUpperCase() === "SNEAK ATTACK"))?.actor;
}

if (!hero) {
  ui.notifications.warn(`No valid Hero found for "Sneak Attack".`);
}
else {
  const sneak = hero.effects.find(fx => fx.name.toUpperCase() === "SNEAK ATTACK");

  if (sneak) {
    const state = sneak.disabled
    await sneak.update({ disabled: !state });
  }
}
